package net.civeira.phylax.feature.observe.observedissue.domain.valueobject;

import org.junit.jupiter.api.Assertions;
import org.junit.jupiter.api.DisplayName;
import org.junit.jupiter.api.Test;

import net.civeira.phylax.common.exception.ConstraintException;

class LastEventIdVOUnitTest {

  /**
   * @autogenerated ValueObjectGenerator
   */
  @Test
  @DisplayName("Test value object contruction for property last event id of observed issue ")
  void test_last_event_id_v_o_builder() {
    Assertions.assertFalse(LastEventIdVO.nullValue().getLastEventId().isPresent(),
        "A empty vo should have a null value");
    Assertions.assertFalse(LastEventIdVO.tryFrom(null).getLastEventId().isPresent(),
        "With a null value, no present result");
    Assertions.assertEquals("one", LastEventIdVO.from("one").getLastEventId().orElse(null));
    Object falingInstance = new Object() {};
    Assertions.assertThrows(ConstraintException.class, () -> LastEventIdVO.tryFrom(falingInstance));
    Assertions.assertEquals("[" + "one" + "]", LastEventIdVO.from("one").toString());
  }
}
